#include <bits/stdc++.h>
using namespace std;

int N, K, res = 1e9;
string S;

int next(int i){ // finds the next empty room
  do {
    i += 1;
  } while(i < N && S[i] == '1');
  return i;
}

int main(){
  cin >> N >> K >> S;
  int l = next(-1), m = l, r = l;
  for(int i = 0; i < K; i++){ // sets up the sliding window
    r = next(r);
  }
  while(r < N){
    while(max(m - l, r - m) > max(next(m) - l, r - next(m))){
      m = next(m);
    }
    res = min(res, max(m - l, r - m));
    l = next(l);
    r = next(r);
  }
  cout << res << 'n';
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1000005;
int N, M, dp[MAXN], res[MAXN];
vector<pair<int,int>> adj[MAXN];

int check(int v){
  if(dp[v]) return dp[v];
  dp[v] = 1;
  for(auto p : adj[v]){
    int n = p.first;
    if(check(n) + 1 > dp[v]){
      dp[v] = dp[n] + 1;
      res[v] = max(res[n], p.second);
    }
  }
  return dp[v];
}

int main(){
  scanf("%d%d", &N, &M);
  for(int i = 0; i < M; i++){
    int a, b;
    scanf("%d%d", &a, &b);
    a -= 1, b -= 1;
    adj[a].push_back({b, i + 1});
  }
  for(int i = 0; i < N; i++){
    if(check(i) == N){
      printf("%dn", res[i]);
      return 0;
    }
  }
  printf("-1n");
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const ll MOD = 1000000007;
const int MAXK = 26;
int N, K, last[MAXK], ord[MAXK];
ll dp[MAXK], sum;
string S;

bool comp(int a, int b){
  return last[a] < last[b];
}

void append(int c){
  sum = (sum - dp[c] + MOD) % MOD;
  dp[c] = (dp[c] + sum + 1) % MOD;
  sum = (sum + dp[c]) % MOD;
}

int main(){
  cin >> N >> K >> S;
  fill(last, last + K, -1);
  for(int i = 0; i < S.size(); i++){
    int c = S[i] - 'a';
    last[c] = i;
    append(c);
  }
  iota(ord, ord + K, 0);
  sort(ord, ord + K, comp);
  for(int i = 0; i < N; i++){
    int c = ord[i % K];
    append(c);
  }
  cout << (sum + 1) % MOD << 'n';
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const ll MOD = 1000000007;
const int MAXN = 200005;
const int MAXA = 1000005;
int N, K, Q, A[MAXN];
int use[MAXA], phi[MAXA], cnt[MAXA];
vector<int> divisors[MAXA];
ll bin[MAXN], res;

ll inv(ll a, ll p){
  if(a == 1) return 1;
  return (p - p / a) * inv(p % a, p) % p;
}

void read(){
  scanf("%d%d%d", &N, &K, &Q);
  for(int i = 0; i < N + Q; i++){
    scanf("%d", &A[i]);
    use[A[i]] = 1;
  }
}

void init(){
  iota(phi, phi + MAXA, 0);
  for(int i = 1; i < MAXA; i++){
    for(int j = i; j < MAXA; j += i){
      if(i != j) phi[j] -= phi[i];
      if(use[j]) divisors[j].push_back(i);
    }
  }
  bin[K - 1] = 1;
  for(int i = K; i < MAXN; i++){
    bin[i] = bin[i - 1] * i % MOD * inv(i - K + 1, MOD) % MOD;
  }
}

int main(){
  read();
  init();
  for(int i = 0; i < N + Q; i++){
    for(int d : divisors[A[i]]){
      res = (res + bin[cnt[d]] * phi[d]) % MOD;
      cnt[d] += 1;
    }
    if(i >= N){
      printf("%dn", res);
    }
  }
}

#include <bits/stdc++.h>
using namespace std;

typedef long double ld;

const ld EPS = 1e-12;
const ld PI = acos(-1);
const int MAXN = 100005;
int N;
ld A, X[MAXN], Y[MAXN];

bool check(ld m){
  ld u = m / 2;
  ld v = sqrt(A * A - u * u);
  vector<pair<ld,ld>> ev;
  for(int i = 0; i < N; i++){
    ld x = 1, y = Y[i] / v, alpha;
    if(X[i] != 0){
      x *= u / X[i], y *= u / X[i];
      ld r = sqrt(x * x + y * y);
      if(r < 1) continue;
      alpha = acos(1 / r);
    } else {
      alpha = PI / 2;
    }
    ld base = atan2(y, x) - alpha;
    if(base < 0) base += 2 * PI;
    ev.push_back({base, base + 2 * alpha});
  }
  priority_queue<ld, vector<ld>, greater<ld>> pq;
  sort(ev.begin(), ev.end());
  for(int i = 0; i < 2; i++){
    for(int j = 0; j < ev.size(); j++){
      while(pq.size() && pq.top() < ev[j].first) pq.pop();
      if(pq.size() && pq.top() < ev[j].second) return 1;
      pq.push(ev[j].second);
      ev[j].first += 2 * PI;
      ev[j].second += 2 * PI;
    }
  }
  return 0;
}

int main(){
  ios::sync_with_stdio(0);
  cin >> N >> A;
  for(int i = 0; i < N; i++){
    cin >> X[i] >> Y[i];
  }
  ld lo = 0, hi = 2 * A;
  while(hi - lo > EPS){
    ld mid = (lo + hi) / 2;
    (check(mid) ? hi : lo) = mid;
  }
  cout << fixed << setprecision(10);
  cout << (lo + hi) / 2 << 'n';
}
